(() => {
  const e2e = window.__e2e;
  // Where to stand to face the next thing: a free spot beside it from which it is nearer than
  // anything else by at least half a tile (run-03a's helper allowed 0.3, and at 2 tiles between two
  // people it stood where the wrong one was nearer). Most margin first, then the nearest walk.
  e2e.spot = async () => {
    const t = await e2e.nextTodo();
    const at = await e2e.pos();
    if (!t || !at) return null;
    const S = await import('/state/index.ts');
    const M = await import('/engine2d/landModel.ts');
    const land = await e2e.shared('land');
    const active = S.useSessionStore.getState().activeInstance;
    const graph = S.useWorldStore.getState().scene.value;
    const seed = land.landSeedOf(active.instance.save);
    const chunks = S.useLandStore.getState().chunks;
    const others = (await e2e.others()).filter((p) => Math.hypot(p[0] - t.at[0], p[1] - t.at[1]) > 0.01);
    const spots = [];
    for (const r of [0.7, 0.9, 1.1]) {
      for (let i = 0; i < 24; i += 1) {
        const a = (i / 24) * Math.PI * 2;
        const p = [t.at[0] + Math.cos(a) * r, t.at[1] + Math.sin(a) * r];
        if (!M.canStandAt(graph, seed, chunks, p[0], p[1], null)) continue;
        const margin = Math.min(99, ...others.map((o) => Math.hypot(o[0] - p[0], o[1] - p[1]) - o[2])) - r;
        if (margin < 0.5) continue;
        spots.push({ p, score: Math.hypot(p[0] - at[0], p[1] - at[1]) - Math.min(margin, 2) });
      }
    }
    spots.sort((a, b) => a.score - b.score);
    return spots[0]?.p ?? t.at;
  };
  return 'spot';
})()
